head.script:
	var searchObj = new SearchObj();

	function movePage(pg){		  
		searchObj.param.page = pg;
		lsSearch();
	}
	
	/* 검색처리   */
	function lsSearch(){							
		var mode = "list";
		// 검색 param 초기화
		/**
		OC 		string(필수) 사용자 이메일의 ID(g4c@korea.kr일경우 OC값=g4c) 
		target 	string : law(필수) 서비스 대상 
		search 	int 검색범위(기본 : 1 법령명) 2 : 본문검색 
		query 		string 법령명에서 검색을 원하는 질의 
		display 	int 검색된 결과 개수 (default=20 max=100) 
		page 		int 검색 결과 페이지 (default=1) 
		sort 		string 정렬옵션(기본 : lasc 법령오름차순) ldes : 법령내림차순 dasc : 공포일자 오름차순 ddes : 공포일자 내림차순 nasc : 공포번호 오름차순 ndes : 공포번호 내림차순  
		date 		int 법령의 공포일자 검색 
		efYd 		string 시행일자 범위 검색(20090101~20090130) 
		ancYd 	string 공포일자 범위 검색(20090101~20090130) 
		ancNo 	string 공포번호 범위 검색(306~400) 
		rrClsCd 	string 법령 제개정 종류(300201-제정/300202-일부개정/300203-전부개정/300204-폐지..) 
		nb 		int 법령의 공포번호 검색 
		org 		string 소관부처별 검색(소관부처코드 제공) 
		knd 		string 법령종류(코드제공) 
		gana 		string 사전식 검색 (ga,na,da…,etc) 
		type 		char 출력 형태 HTML/XML 생략시 기본값 : HTML 
		**/
		searchObj.param.OC = el("OC").value;	
		searchObj.param.target = el("target").value;		
		searchObj.param.search = el("search").value;		
		searchObj.param.query = el("query").value;		
		searchObj.param.display = el("display").value;		
		searchObj.param.sort = el("sort").value;		
		searchObj.param.date = el("date").value;
		
		searchObj.param.efYd = el("efYd").value;
		searchObj.param.ancYd = el("ancYd").value;
		searchObj.param.ancNo = el("ancNo").value;
		searchObj.param.rrClsCd = el("rrClsCd").value;
		
		searchObj.param.nb = el("nb").value;		
		searchObj.param.org = el("org").value;		
		searchObj.param.knd = el("knd").value;		
		searchObj.param.gana = el("gana").value;		
		searchObj.param.nw = el("nw").value;		
		searchObj.param.refAdr = el("refAdr").value;
		searchObj.param.ID = el("ID").value;
		searchObj.param.type = "HTML";		
		searchObj.param.popYn = el("popYn").value;	
		fLsUpdate("/DRF/lawSearch.do", makeParam(searchObj.param));
	}
	
	function fLsUpdate(urlName,parameter){
		location.href = "/DRF/lawSearch.do?"+parameter;
	}

	function openPop(thisUrl){
		var popUrl = thisUrl;
		var contentPop = window.open('','', 'scrollbars=no,toolbar=no,resizable=yes,status=no,menubar=no');
		contentPop.location.href = popUrl;

	}
